// Benchmarks against real Australian Google Business Profiles.
//
// Every other local SEO tool answers "how many reviews should I have?" with a
// number someone made up, or an American survey from years ago. These come out
// of our own Maps scrape, per Google primary category. src/benchmarks.js is
// generated by tools/build-benchmarks.mjs.
import { CATEGORIES, TRADE_MAP, OVERALL, MIN_SAMPLE, GENERATED } from "./benchmarks.js";

const SOURCE = `Source: our own scrape of ${OVERALL.n.toLocaleString("en-AU")} Australian Google Business Profiles across ${OVERALL.suburbs.toLocaleString("en-AU")} suburbs (${GENERATED}), per Google primary category. Convenience sample, metro-skewed, leans to trades and service businesses, so treat small categories as indicative. Full method and the raw CSV are published under /research on the site linked below.`;

const norm = (s) => String(s || "").toLowerCase().trim().replace(/\s+/g, " ");
const singular = (s) => norm(s).replace(/s$/, "");

/** Find the benchmark row for a Google category name, or a plain-English trade word. */
export function resolveCategory(input) {
  const q = norm(input);
  if (!q) return null;
  if (CATEGORIES[q]) return { key: q, row: CATEGORIES[q], how: "exact" };

  // Plain-English trade word: use what real businesses in that trade actually pick.
  const trade = TRADE_MAP[q] || TRADE_MAP[q + "s"] || TRADE_MAP[singular(q)];
  if (trade) {
    const top = trade.categories.find((c) => CATEGORIES[norm(c.label)]);
    if (top) return { key: norm(top.label), row: CATEGORIES[norm(top.label)], how: "trade", trade };
  }

  // Loose contains match, longest label first so "carpet cleaning service" beats "cleaners".
  const hit = Object.keys(CATEGORIES)
    .filter((k) => k.includes(q) || q.includes(k))
    .sort((a, b) => b.length - a.length)[0];
  return hit ? { key: hit, row: CATEGORIES[hit], how: "fuzzy" } : null;
}

/** Where a value sits in a p10..p90 ladder, interpolated, clamped to 1-99. */
function percentile(value, p) {
  if (!Number.isFinite(value)) return null;
  const pts = [[p.p10, 10], [p.p25, 25], [p.p50, 50], [p.p75, 75], [p.p90, 90]].filter(([v]) => Number.isFinite(v));
  if (!pts.length) return null;
  if (value <= pts[0][0]) return Math.max(1, Math.round((value / Math.max(pts[0][0], 1)) * pts[0][1]));
  for (let i = 0; i < pts.length - 1; i++) {
    const [v1, q1] = pts[i], [v2, q2] = pts[i + 1];
    if (value <= v2) {
      const span = v2 - v1;
      return Math.round(span <= 0 ? q2 : q1 + ((value - v1) / span) * (q2 - q1));
    }
  }
  return Math.min(99, Math.round(90 + (value / Math.max(pts[pts.length - 1][0], 1) - 1) * 9));
}

const ord = (n) => {
  const t = n % 100;
  if (t >= 11 && t <= 13) return `${n}th`;
  return `${n}${["th", "st", "nd", "rd"][n % 10] || "th"}`;
};
const article = (w) => (/^[aeiou]/i.test(String(w).trim()) ? "an" : "a");

// Returns a clause that reads correctly after "<n> puts X ...".
const place = (q) =>
  q >= 90 ? "in the top 10% of its category" :
  q >= 75 ? "in the top quarter" :
  q >= 50 ? "above the middle" :
  q >= 25 ? "below the middle" : "in the bottom quarter";

export function benchmarkBusiness({ category = "", trade = "", review_count, rating, business_name = "" } = {}) {
  const found = resolveCategory(category) || resolveCategory(trade);
  const who = business_name ? `"${business_name}"` : "This business";
  const L = [];

  if (!found) {
    const asked = [category, trade].filter(Boolean).join(" / ") || "(nothing given)";
    L.push(`No Australian benchmark for ${asked}.`);
    L.push(`We only publish a category once we have at least ${MIN_SAMPLE} businesses in it, because a percentile off a handful of listings is noise. ${Object.keys(CATEGORIES).length} categories qualify.`);
    L.push(`Whole-sample fallback, every category together: median ${OVERALL.reviews.p50} reviews, median ${OVERALL.rating.p50} stars, and ${OVERALL.nameNotCleanPct}% of names get flagged by the basic name check for a closer look. That is not a count of rule breaks: most flags are a service word or suburb in a genuine brand, which Google allows.`);
    L.push("");
    L.push(SOURCE);
    return { text: L.join("\n") };
  }

  const { row, how, trade: tradeHit } = found;
  L.push(`Benchmark: ${row.label} (${row.n} Australian businesses in the sample)`);
  if (how === "trade" && tradeHit) L.push(`Matched "${trade || category}" to the category ${row.label}, which ${tradeHit.categories[0].pct}% of them use.`);
  if (how === "fuzzy") L.push(`Closest category we have data for. Treat it as indicative.`);
  L.push("");

  const revs = Number.isFinite(review_count) ? review_count : null;
  if (revs !== null) {
    const q = percentile(revs, row.reviews);
    L.push(`Reviews: ${revs} puts ${who} ${place(q)} (about the ${ord(q)} percentile).`);
    L.push(`  The ladder: ${row.reviews.p10} (bottom 10%) · ${row.reviews.p25} · ${row.reviews.p50} (median) · ${row.reviews.p75} · ${row.reviews.p90} (top 10%).`);
    const next = [["the median", row.reviews.p50], ["the top quarter", row.reviews.p75], ["the top 10%", row.reviews.p90]].find(([, v]) => v > revs);
    if (next) {
      const gap = next[1] - revs;
      L.push(`  ${gap} more review${gap === 1 ? "" : "s"} clears ${next[0]}. At 4 a month that is ${Math.ceil(gap / 4)} month${Math.ceil(gap / 4) === 1 ? "" : "s"}.`);
    } else {
      L.push(`  Already past the top 10% for this category. Review volume is not the constraint here.`);
    }
  } else {
    L.push(`Reviews: no count given. The ladder for ${row.label}: ${row.reviews.p10} · ${row.reviews.p25} · ${row.reviews.p50} (median) · ${row.reviews.p75} · ${row.reviews.p90}.`);
  }
  L.push("");

  if (row.rating) {
    const rat = Number.isFinite(rating) ? rating : null;
    if (rat !== null) {
      const q = percentile(rat, row.rating);
      L.push(`Rating: ${rat} sits ${place(q)} (about the ${ord(q)} percentile).`);
      L.push(`  The ladder: ${row.rating.p10} · ${row.rating.p25} · ${row.rating.p50} (median) · ${row.rating.p75} · ${row.rating.p90}.`);
      if (q >= 75) L.push(`  Genuinely ahead of this category. Protect it: one unanswered bad review moves a rating this high more than it moves anyone else's.`);
      else if (q >= 50) L.push(`  Mid-pack. In this category a rating here is the normal range rather than a selling point, so review volume is what separates you.`);
      else L.push(`  Below the median for this category. Find the cause before chasing more reviews, or you scale the problem.`);
    } else {
      L.push(`Rating ladder for ${row.label}: ${row.rating.p10} · ${row.rating.p25} · ${row.rating.p50} (median) · ${row.rating.p75} · ${row.rating.p90}.`);
    }
    L.push("");
  }

  L.push(`Names: ${row.nameNotCleanPct}% of ${row.label} listings in the sample get flagged by the basic name check for a closer look, against ${OVERALL.nameNotCleanPct}% across every category.`);
  L.push(`  A flag is not a rule break. A service word or suburb in the name is allowed when it is the genuine real-world brand, which is the usual case. Run verify_business_name with the website before calling any name a problem or reporting a competitor.`);
  L.push("");
  L.push(SOURCE);
  return { text: L.join("\n") };
}

export function pickCategory({ trade = "", services = [] } = {}) {
  const q = norm(trade);
  const hit = TRADE_MAP[q] || TRADE_MAP[q + "s"] || TRADE_MAP[singular(q)];
  const L = [];

  if (!hit) {
    const near = Object.keys(TRADE_MAP).filter((k) => k.includes(q) || q.includes(k)).slice(0, 8);
    L.push(`No Australian category data for "${trade || "(nothing given)"}".`);
    if (near.length) L.push(`Closest trades we do have: ${near.join(", ")}.`);
    L.push(`What to do instead: search your trade plus your suburb in Google Maps, open the top 3 listings and read the category under each name. Pick the one at least two of them use.`);
    L.push("");
    L.push(SOURCE);
    return { text: L.join("\n") };
  }

  L.push(`Primary category for ${article(trade)} ${trade}, from ${hit.n} real Australian listings:`);
  L.push("");
  hit.categories.forEach((c, i) => {
    const b = CATEGORIES[norm(c.label)];
    L.push(`${i === 0 ? "USE THIS" : "  also seen"}: ${c.label} — ${c.pct}% of them (${c.n}/${hit.n})${b ? `, median ${b.reviews.p50} reviews` : ""}`);
  });
  L.push("");
  L.push(`Primary category is the single biggest ranking lever on a profile and the hardest to undo a mistake on, so match the pack rather than picking the most flattering label. "${hit.categories[0].label}" is what ${hit.categories[0].pct}% of them use.`);
  if (hit.categories.length > 1) {
    L.push(`The rest above are fine as ADDITIONAL categories if you genuinely do that work. Additional categories cost you nothing; a wrong primary costs you the map pack.`);
  }
  if (services.length) {
    L.push("");
    L.push(`You listed: ${services.join(", ")}. Add an additional category for each of those you actually do and Google has a category for, then list them again under Services with a line of description each.`);
  }
  L.push("");
  L.push(SOURCE);
  return { text: L.join("\n") };
}

export const BENCHMARK_META = { OVERALL, GENERATED, count: Object.keys(CATEGORIES).length };
